MineData AntipersonelMine { className = "Mine"; description = "Antipersonel Mine"; shapeFile = "mine"; shadowDetailMask = 4; explosionId = mineExp; explosionRadius = 10.0; damageValue = 0.65; damageType = $MineDamageType; kickBackStrength = 150; triggerRadius = 2.5; maxDamage = 0.5; shadowDetailMask = 0; destroyDamage = 1.0; damageLevel = {1.0, 1.0}; };
function AntipersonelMine::onAdd(%this) { %this.damage = 0; AntipersonelMine::deployCheck(%this); }
function AntipersonelMine::onCollision(%this,%object) { %type = getObjectType(%object); %data = GameBase::getDataName(%this); if ((%type == "Player" || %data == AntipersonelMine || %data == ConcussionMine || %data == EMPMine || %data == CloakedMine || %data == Vehicle || %type == "Moveable") && GameBase::isActive(%this)) GameBase::setDamageLevel(%this, %data.maxDamage); }
function AntipersonelMine::deployCheck(%this) { if (GameBase::isAtRest(%this)) { GameBase::playSequence(%this,1,"deploy"); GameBase::setActive(%this,true); %set = newObject("set",SimSet); if(1 != containerBoxFillSet(%set,$MineObjectType,GameBase::getPosition(%this),1,1,1,0)) { %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } deleteObject(%set); } else schedule("AntipersonelMine::deployCheck(" @ %this @ ");", 3, %this); }
function AntipersonelMine::onDestroyed(%this) { $TeamItemCount[GameBase::getTeam(%this) @ "mineammo"]--; }
function AntipersonelMine::onDamage(%this,%type,%value,%pos,%vec,%mom,%object) { if (%type == $MineDamageType || %type == $ConcussionMineDamageType || %type == $EMPMineDamageType || %type == $CloakedMineDamageType) %value = %value * 0.25; %data = GameBase::getDataName(%this); if((%data.maxDamage/1.5) < %this.damage+%value) GameBase::setDamageLevel(%this, %data.maxDamage); else %this.damage += %value; }

MineData ConcussionMine { className = "Mine"; description = "Concussion Mine"; shapeFile = "mine"; shadowDetailMask = 4; explosionId = LargeShockwave; explosionRadius = 10.0; damageValue = 0.01; damageType = $ConcussionMineDamageType; kickBackStrength = 50; triggerRadius = 2.5; maxDamage = 0.5; shadowDetailMask = 0; destroyDamage = 1.0; damageLevel = {1.0, 1.0}; };
function ConcussionMine::onAdd(%this) { %this.damage = 0; ConcussionMine::deployCheck(%this); }
function ConcussionMine::onCollision(%this,%object) { %type = getObjectType(%object); %data = GameBase::getDataName(%this); if ((%type == "Player" || %data == AntipersonelMine || %data == ConcussionMine || %data == EMPMine || %data == CloakedMine || %data == Vehicle || %type == "Moveable") && GameBase::isActive(%this)) GameBase::setDamageLevel(%this, %data.maxDamage); }
function ConcussionMine::deployCheck(%this) { if (GameBase::isAtRest(%this)) { %pos = GameBase::getPosition(%this); if(!ixCheckFlagProx(getWord(%pos, 0), getWord(%pos, 1), getWord(%pos, 2), 12)) { GameBase::playSequence(%this,1,"deploy"); GameBase::setActive(%this,true); %set = newObject("set",SimSet); if(1 != containerBoxFillSet(%set,$MineObjectType,GameBase::getPosition(%this),1,1,1,0)) { %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } deleteObject(%set); } else { Client::sendMessage(%this.pxOwner,0,"You may not place Concussion Mines this close to the flag."); %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } } else schedule("ConcussionMine::deployCheck(" @ %this @ ");", 3, %this); }
function ConcussionMine::onDestroyed(%this) { }
function ConcussionMine::onDamage(%this,%type,%value,%pos,%vec,%mom,%object) { if (%type == $MineDamageType || %type == $ConcussionMineDamageType || %type == $EMPMineDamageType || %type == $CloakedMineDamageType) %value = %value * 0.25; %data = GameBase::getDataName(%this); if((%data.maxDamage/1.5) < %this.damage+%value) GameBase::setDamageLevel(%this, %data.maxDamage); else %this.damage += %value; }

