function EMPMine::onCollision(%this,%object) { %type = getObjectType(%object); %data = GameBase::getDataName(%this); if ((%type == "Player" || %data == AntipersonelMine || %data == ConcussionMine || %data == EMPMine || %data == CloakedMine || %data == Vehicle || %type == "Moveable") && GameBase::isActive(%this)) GameBase::setDamageLevel(%this, %data.maxDamage); }
function EMPMine::deployCheck(%this) { if (GameBase::isAtRest(%this)) { %pos = GameBase::getPosition(%this); if(!ixCheckFlagProx(getWord(%pos, 0), getWord(%pos, 1), getWord(%pos, 2), 12)) { GameBase::playSequence(%this,1,"deploy"); GameBase::setActive(%this,true); %set = newObject("set",SimSet); if(1 != containerBoxFillSet(%set,$MineObjectType,GameBase::getPosition(%this),1,1,1,0)) { %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } deleteObject(%set); } else { Client::sendMessage(%this.pxOwner,0,"You may not place EMP Mines this close to the flag."); %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } } else schedule("EMPMine::deployCheck(" @ %this @ ");", 3, %this); }
function EMPMine::onDestroyed(%this) { }
