MineData CloakedMine { className = "Mine"; description = "Cloaked Mine"; shapeFile = "mine"; shadowDetailMask = 4; explosionId = mineExp; explosionRadius = 10.0; damageValue = 0.325; damageType = $CloakedMineDamageType; kickBackStrength = 100; triggerRadius = 2.0; maxDamage = 0.5; shadowDetailMask = 0; destroyDamage = 1.0; damageLevel = {1.0, 1.0}; };
function CloakedMine::onAdd(%this) { %this.damage = 0; CloakedMine::deployCheck(%this); }
function CloakedMine::onCollision(%this,%object) { %type = getObjectType(%object); if(%type == "Player") { %objectClient = Player::getClient(%object); %objectTeam = Client::getTeam(%objectClient); } %thisTeam = Client::getTeam(%this.pxOwner); %data = GameBase::getDataName(%this); if(%type == "Player" && %objectTeam != %thisTeam) { if((%data == AntipersonelMine || %data == ConcussionMine || %data == EMPMine || %data == CloakedMine || %data == Vehicle || %type == "Moveable") && GameBase::isActive(%this)) GameBase::setDamageLevel(%this, %data.maxDamage); } else { GameBase::setDamageLevel(%this, 0); if(%type == "Player") Client::sendMessage(%objectClient,0,"You can not trigger your own team's Cloaked Mines."); } }
function CloakedMine::deployCheck(%this) { if (GameBase::isAtRest(%this)) { %pos = GameBase::getPosition(%this); if(!ixCheckFlagProx(getWord(%pos, 0), getWord(%pos, 1), getWord(%pos, 2), 12)) { GameBase::playSequence(%this,1,"deploy"); GameBase::setActive(%this,true); %set = newObject("set",SimSet); if(1 != containerBoxFillSet(%set,$MineObjectType,GameBase::getPosition(%this),1,1,1,0)) { %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } deleteObject(%set); pxCloakMine(%this); } else { Client::sendMessage(%this.pxOwner,0,"You may not place Cloaked Mines this close to the flag."); %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); } } else schedule("CloakedMine::deployCheck(" @ %this @ ");", 3, %this); }
function CloakedMine::onDestroyed(%this) { $pxStopMinePing[%this] = true; }
function CloakedMine::onDamage(%this,%type,%value,%pos,%vec,%mom,%object) { if (%type == $MineDamageType || %type == $ConcussionMineDamageType || %type == $EMPMineDamageType || %type == $CloakedMineDamageType) %value = %value * 0.25; %data = GameBase::getDataName(%this); if((%data.maxDamage/1.5) < %this.damage+%value) GameBase::setDamageLevel(%this, %data.maxDamage); else %this.damage += %value; }
function pxCloakMine(%this) { $pxStopMinePing[%this] = false; GameBase::startFadeout(%this); schedule("pxMinePing(" @ %this @ ");", 2, %this); }
function pxMinePing(%this) { if($pxStopMinePing[%this] != true) { playSound(SoundCloakedMinePing,GameBase::getPosition(%this)); schedule("pxMinePing(" @ %this @ ");",1.5, %this); } }

MineData Handgrenade { mass = 0.3; drag = 1.0; density = 2.0; elasticity = 0.15; friction = 1.0; className = "Handgrenade"; description = "Handgrenade"; shapeFile = "grenade"; shadowDetailMask = 4; explosionId = grenadeExp; explosionRadius = 10.0; damageValue = 0.5; damageType = $ShrapnelDamageType; kickBackStrength = 100; triggerRadius = 0.5; maxDamage = 2; };
function Handgrenade::onAdd(%this) { %data = GameBase::getDataName(%this); schedule("Mine::Detonate(" @ %this @ ");",2.0,%this); }

function Mine::onDamage(%this,%type,%value,%pos,%vec,%mom,%object) { if (%type == $MineDamageType || %type == $ConcussionMineDamageType || %type == $EMPMineDamageType || %type == $CloakedMineDamageType) %value = %value * 0.25; %damageLevel = GameBase::getDamageLevel(%this); GameBase::setDamageLevel(%this,%damageLevel + %value); }
function Mine::Detonate(%this) { %data = GameBase::getDataName(%this); GameBase::setDamageLevel(%this, %data.maxDamage); }

MineData Detonate { mass = 0.3; drag = 1.0; density = 2.0; elasticity = 0.15; friction = 1.0; className = "Handgrenade"; description = "Handgrenade"; shapeFile = "mortarpack"; shadowDetailMask = 4; explosionId = DetonationExp; explosionRadius = 10.0; damageValue = 0.5; damageType = $DebrisDamageType; kickBackStrength = 100; triggerRadius = 0.5; maxDamage = 2; };
